def linear(label,original,answer,conditions,kp):
 p=reasoning(label,answer,'Take logarithms of the ORIGINAL relation with positive arguments. Identify the actual plotted dependent and independent variables before identifying the coefficient of X and the constant term. '+conditions,kp,'matches')
 p.update(original_relation=original,assessed_8227_demand_ids=[LIN],response_format='symbolic',domain_conditions=conditions)
 return p
def scalar(label,expr,key,kp,dp=None,sf=None):
 p=v(label,expr,key,kp,'Derive gradient and intercept from the ORIGINAL supplied transformed-axis coordinates,not from raw x,y guesses. Recover each model parameter using the correct exponential/inverse logarithm and round only the final result. A slope is not automatically the original exponential base.')
 p.update(assessed_8227_demand_ids=[CONSTANTS],response_format='numeric',given_representation='graph')
 if dp is not None:p['operation']={'kind':'rounded','operands':[expr],'decimal_places':dp};p['requested_precision']=str(dp)+' decimal places'
 if sf:p['operation']={'kind':'rounded','operands':[expr],'significant_figures':sf};p['requested_precision']=str(sf)+' significant figures'
 return p
